    'Ik aanvaard de bevoegdheid van de Amerikaanse federale districtsrechtbank voor mijn adres — of, als mijn adres buiten de VS ligt, van elk gerechtelijk district waar Hevalo te vinden is — en ik aanvaard betekening van stukken door wie de melding stuurde of diens vertegenwoordiger.',
  'copyright.counter.send': 'Tegenmelding sturen',
  'copyright.counter.cancel': 'Annuleren',
  'copyright.counter.sentTitle': 'Je tegenmelding is verstuurd.',
  'copyright.counter.sentBody':
    'We sturen een kopie naar wie de melding stuurde. Laat die ons niet weten dat die naar de rechter is gestapt, dan kan je bericht vanaf {date} terugkomen, nadat een mens bij Hevalo het heeft bekeken.',
  'copyright.counter.done': 'Klaar',
  'copyright.counter.error.already': 'Je hebt hiervoor al een tegenmelding gestuurd.',
  'copyright.counter.error.closed': 'De termijn voor een tegenmelding hiervoor is verlopen.',
  'copyright.repeat.title': 'Herhaald kopiëren',
  'copyright.repeat.body':
    'Worden binnen twaalf maanden drie auteursrechtmeldingen tegen iemands berichten bevestigd, dan kunnen we diens account sluiten. Een verwijdering die na een herbeoordeling of tegenmelding is teruggedraaid, telt niet mee.',
  'copyright.agent.title': 'Aangewezen DMCA-agent',
  'copyright.agent.lead': 'Voor meldingen onder de Amerikaanse DMCA kun je ook onze aangewezen agent schrijven:',
