  'terms.summary.title': 'In het kort',
  'terms.summary.kind': 'Wees aardig. Geen pesten, haat, bedreigingen of inhoud voor volwassenen.',
  'terms.summary.own':
    'Plaats wat je zelf gemaakt hebt. Deel je woorden of een afbeelding van iemand anders? Alleen als het mag — en zeg van wie het is.',
  'terms.summary.yours':
    'Wat je plaatst, blijft van jou. We laten het alleen zien aan de mensen die je instellingen toelaten.',
  'terms.summary.rules':
    'Breek je de regels, dan kunnen we berichten verwijderen of je account beperken. We zeggen altijd waarom, en je kunt ons vragen opnieuw te kijken.',
  'terms.summary.zer': 'Zêr bestaat alleen in Hevalo. Het is geen echt geld.',
  'terms.summary.leave': 'Je kunt je account altijd verwijderen via Instellingen.',
  'terms.provider.title': 'Wie Hevalo aanbiedt',
  'terms.provider.lead': 'Hevalo wordt aangeboden door:',
  'terms.warranty.title': 'Plaats alleen wat mag',
  'terms.warranty.body':
    'Als je iets plaatst, beloof je dat je het zelf gemaakt hebt of het mag plaatsen: het is vrij te gebruiken, je hebt toestemming, of de wet staat het toe — zoals een kort citaat met bron. Plaats geen foto’s, kunst, songteksten of vertalingen van anderen zonder hun toestemming.',
  'terms.licence.title': 'Wat je ons daarmee toestaat',
  'terms.licence.body':
    'Om Hevalo te laten werken, moeten we bewaren wat je plaatst, er kopieën van maken (kleinere formaten, back-ups, kopieën op de servers die het leveren) en het tonen aan de mensen die je instellingen toelaten. Meer sta je ons niet toe: we verkopen het niet en gebruiken het niet in reclame. Dit stopt als je het verwijdert, behalve voor back-ups en kopieën die we wettelijk kort moeten bewaren.',
  'terms.notices.title': 'Auteursrechtmeldingen',
  'terms.notices.body':
    'Iedereen die denkt dat iets hier zijn werk kopieert, kan dat via de pagina Auteursrecht melden, ook zonder account. Verwijderen we je bericht door een melding, dan zeggen we waarom, en kun je een tegenmelding sturen of een herbeoordeling vragen.',
  'terms.notices.link': 'Naar de pagina Auteursrecht',
  'terms.moderationHow':
    'Als we iets verwijderen of je account beperken, zeggen we waarom en welke regel is overtreden. Over meldingen en auteursrechtmeldingen beslist een mens; sommige controles, zoals een limiet op hoe snel je kunt plaatsen, zijn automatisch. Je kunt binnen zes maanden een herbeoordeling vragen via Accountstatus.',
  'terms.repeat.title': 'Herhaald kopiëren',
  'terms.repeat.body':
    'Worden binnen twaalf maanden drie auteursrechtmeldingen tegen jouw berichten bevestigd, dan kunnen we je account sluiten. Een verwijdering die na een herbeoordeling of tegenmelding is teruggedraaid, telt niet mee.',
  'terms.shopArt.title': 'Items uit de winkel',
  'terms.shopArt.body':
    'Achtergronden en iconen uit de winkel zijn afbeeldingen voor je profiel, gemaakt door Hevalo. We kunnen een item opnieuw tekenen of uit de winkel halen. Items die je hebt, blijven van jou, met de nieuwe afbeelding, en als we items veranderen die je kocht, laten we het je weten.',
  'terms.contact.title': 'Zo bereik je ons',
  'terms.contact.lead': 'Schrijf ons in een van de genoemde talen. Een mens antwoordt.',
  'terms.law.title': 'Welk recht geldt',
  'terms.law.body':
    'Op deze voorwaarden is Nederlands recht van toepassing. Woon je in een ander land van de Europese Unie, dan houd je ook de bescherming die het consumentenrecht van je eigen land je geeft.',
  'terms.responsibility.title': 'Waarvoor wij verantwoordelijk zijn',
  'terms.responsibility.body':
    'Hevalo laat zien wat leden plaatsen, maar we controleren niet alles voordat het verschijnt, en iedereen is zelf verantwoordelijk voor wat hij of zij plaatst. Horen we dat iets in strijd is met de wet of met deze voorwaarden, dan grijpen we snel in. We doen ons best om Hevalo goed te laten werken, maar we kunnen niet beloven dat het altijd beschikbaar of foutloos is. We zijn aansprakelijk voor schade die we opzettelijk of door grove nalatigheid veroorzaken, en voor alles waarvoor de wet ons verder aansprakelijk stelt. Niets hierin neemt je rechten af die de wet je geeft.',
