  'games.sentence.why.negation': 'Het Koerdisch zet ‘niet’ op het werkwoord zelf, vooraan, dus het werkwoord blijft achteraan.',
  'games.sentence.why.ezafe': 'De ezafe verbindt een woord met het woord dat het beschrijft of bezit, en het beschrijvende woord komt erna.',
  'games.sentence.why.verb-final': 'Het onderwerp komt eerst en het werkwoord als laatste, met tijd, plaats en lijdend voorwerp ertussen.',
  'games.sentence.why.two-clauses': 'Elke deelzin houdt zijn eigen volgorde, met het werkwoord aan het eind; het verbindingswoord opent de tweede.',
