  'landing.stories.them': 'Andere apps geven je lessen.',
  'landing.stories.us': 'Hevalo geeft je iemand om ze tegen te zeggen.',
  'landing.stories.lead': 'Elk woord dat je leert, kan ergens heen: een spel met een vriend, een brief aan een penvriend, de volgende stop op je weg.',
  'landing.stories.label': 'Drie scènes uit Hevalo',
