  'landing.stories.note': 'Scènes uit de app, getekend voor deze pagina.',
  'landing.story.game.label': 'Rojîn nodigt je uit voor een Peyvok-duel. Jullie raden om het snelst hetzelfde Koerdische woord, en jij hebt het in drie pogingen: heval, dat betekent vriend. Rojîn schrijft terug: Aferîn, goed gedaan!',
  'landing.story.letter.from': 'Een brief van {name}',
  'landing.story.letter.label': 'De duif van Dilan vliegt met een brief door je raam naar binnen en legt hem op de vensterbank. Hij gaat open: Silav heval! Tu çawa yî? Ez baş im, spas. Dat is: Hallo, vriend! Hoe gaat het met je? Goed, dank je.',
  'landing.story.road.label': 'Hevalo loopt het eerste hoofdstuk van de weg, Silav. De les die hij afmaakt, krijgt een stempel, de volgende gaat open, en je reeks gaat van drie naar vier dagen. Hij loopt verder en maakt ook de volgende les af.',
  'landing.story.road.streak': '{n} dagen op rij',
  'landing.table.them': 'De meeste apps leren je een koffie bestellen.',
