  'landing.table.us.anyone': 'Hevalo leert je praten met de mensen van wie je houdt.',
  'landing.table.lead.family': 'De weg begint met de woorden die als eerste terugkomen: een welkom aan de deur, thee en de vragen van een oma.',
  'landing.table.lead.partner': 'De weg begint aan een Koerdische tafel, met wat de familie als eerste tegen je zegt: een welkom, thee en hoe gaat het.',
  'landing.table.lead.children': 'De weg begint met wat een familie elke dag zegt, zodat je kinderen het van jou horen.',
